import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { FlankerTestMouseData } from '../models/FlankerTestMouseData';
import { Observable } from 'rxjs/internal/Observable';

@Injectable({
  providedIn: 'root'
})
export class FlankerTestDataTransferService {
  private apiUrl = 'http://localhost:4000/flanker/sendData';

  constructor(private http: HttpClient) {}

  sendMouseData(iteration: number, isCorrect: boolean, reactionTime: number, events: FlankerTestMouseData[], sessionId: string ): Observable<any> {
    const payload = {
      iteration,
      isCorrect,
      reactionTime,
      events,
      sessionId
    };

    return this.http.post(this.apiUrl, payload);
  }
}


